SHELL_COMMON = r'''#!/usr/bin/env bash
# Shared host-side helpers. Sourced by experiment scripts on the lab host.
set -euo pipefail

lab_root() {
  local here="$1"
  (cd "$here" && while [[ ! -f LICENSE || ! -f AGENTS.md ]]; do
    cd ..
    if [[ "$(pwd)" == "/" ]]; then
      echo "labctl: repository root not found" >&2
      return 1
    fi
  done
  pwd)
}

log() { printf '[labctl] %s\n' "$*"; }
die() { printf '[labctl] ERROR: %s\n' "$*" >&2; exit 1; }

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "missing command: $1"
}

utc_now() { date -u +%Y-%m-%dT%H:%M:%SZ; }
'''

SHELL_EVIDENCE = r'''#!/usr/bin/env bash
# Hash a directory tree to manifests/evidence.sha256
hash_tree() {
  local src="$1"
  local dest="$2"
  mkdir -p "$(dirname "$dest")"
  (cd "$src" && find . -type f -print0 | sort -z | xargs -0 sha256sum) > "$dest"
  log "wrote $dest"
}
'''
